trait Weight { fn weight(&self) -> u32; }
struct Parcel { grams: u32 }
impl Weight for Parcel {
    fn weight(&self) -> u32 { self.grams }
}
fn total<T: Weight>(items: &[T]) -> u32 {
    items.iter().map(|item| item.weight()).sum()
}
fn main() {
    println!("{}", total(&[Parcel { grams: 3 }, Parcel { grams: 4 }]));
}

