trait Weight { fn weight(&self) -> u32; }
struct Crate { contents: u32, packaging: u32 }
impl Weight for Crate {
    fn weight(&self) -> u32 { self.contents + self.packaging }
}
fn main() {
    let item = Crate { contents: 7, packaging: 2 };
    assert_eq!(item.weight(), 9);
    println!("{}", item.weight());
}

