fn next_multiple_of_three(n: u32) -> u32 {
    n + (3 - n % 3) % 3
}
fn main() {
    assert_eq!(next_multiple_of_three(0), 0);
    assert_eq!(next_multiple_of_three(4), 6);
    assert_eq!(next_multiple_of_three(6), 6);
    println!("checks passed");
}

