let parse_positive text =
  match int_of_string_opt text with
  | Some n when n > 0 -> Ok n
  | _ -> Error "positive integer required"
let double_input text = Result.map (fun n -> n * 2) (parse_positive text)
let show = function
  | Ok n -> Printf.printf "%d\n" n
  | Error message -> print_endline message
let () =
  show (double_input "4");
  show (double_input "bad")

structure Progress where
  completed : Nat
  total : Nat
def advance (p : Progress) : Progress :=
  { p with completed := p.completed + 1 }
def start : Progress := { completed := 2, total := 5 }
#eval start.completed
#eval (advance start).completed
